import{_ as e,c as d,a0 as o,o as a}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"S2.5: 质量门禁 - 状态权威偏差表","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/state-authority.md","filePath":"architecture/state-authority.md"}'),r={name:"architecture/state-authority.md"};function c(i,t,s,n,l,u){return a(),d("div",null,t[0]||(t[0]=[o('<h1 id="s2-5-质量门禁-状态权威偏差表" tabindex="-1">S2.5: 质量门禁 - 状态权威偏差表 <a class="header-anchor" href="#s2-5-质量门禁-状态权威偏差表" aria-label="Permalink to &quot;S2.5: 质量门禁 - 状态权威偏差表&quot;">​</a></h1><blockquote><p>审计时间：2026-05-16 任务：s2.5-1（质量门禁） 前提：S2-abc 和 S2-def 都完成</p></blockquote><h2 id="_1-状态权威分析" tabindex="-1">1. 状态权威分析 <a class="header-anchor" href="#_1-状态权威分析" aria-label="Permalink to &quot;1. 状态权威分析&quot;">​</a></h2><h3 id="_1-1-所有状态汇总" tabindex="-1">1.1 所有状态汇总 <a class="header-anchor" href="#_1-1-所有状态汇总" aria-label="Permalink to &quot;1.1 所有状态汇总&quot;">​</a></h3><p>基于系统审计分析，汇总如下：</p><table tabindex="0"><thead><tr><th>状态</th><th>文件</th><th>应有权威</th><th>当前实际权威</th><th>偏差说明</th><th>严重程度</th></tr></thead><tbody><tr><td>播放状态（is_playing）</td><td><code>device_player.py</code></td><td><code>device_player.py</code></td><td><code>device_player.py</code> + <code>xiaomusic.xiaomusic</code>（通过 xiaomusic 实例访问）</td><td>当前权威正确，但 device_player 直接持有 xiaomusic 引用，访问路径不干净</td><td>低</td></tr><tr><td>歌单事实与设备运行时队列</td><td><code>music_library.py</code> / <code>device_player.py</code></td><td><code>music_library</code> 拥有 membership；<code>device_player</code> 拥有当前 session 快照与索引</td><td>职责已分离</td><td><code>_play_list_items</code> 是从歌单事实建立的 session 快照，不得写回或在 next/previous 时重建</td><td>无</td></tr><tr><td>认证状态（auth_state）</td><td><code>auth.py</code></td><td><code>auth.py</code></td><td><code>auth.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>Auth token（_mina_token）</td><td><code>auth.py</code></td><td><code>auth.py</code></td><td><code>auth.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>runtime_auth_ready</td><td><code>auth.py</code></td><td><code>auth.py</code></td><td><code>auth.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>设备列表（devices）</td><td><code>device_manager.py</code></td><td><code>device_manager.py</code></td><td><code>device_manager.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>设备播放状态（cur_music, entity_id）</td><td><code>device.model</code></td><td><code>device_player.py</code>（播放控制者）</td><td><code>device_player.py</code> 更新 + <code>device.model</code> 持有</td><td>device model 作为数据容器被直接修改，缺少通过 player 的封装</td><td>低</td></tr><tr><td>Source 插件注册（_plugins）</td><td><code>source_registry.py</code></td><td><code>source_registry.py</code></td><td><code>default_registry.py</code>（注册时）+ <code>source_plugin_manager.py</code>（管理）</td><td>注册逻辑分散在 default_registry，source_registry 只负责查找，职责分离不清</td><td>低</td></tr><tr><td>流会话状态（session.state）</td><td><code>stream_session_manager.py</code></td><td><code>stream_session_manager.py</code></td><td><code>stream_session_manager.py</code> + <code>relay_runtime.py</code>（多处直接修改）</td><td>RelayRuntime._stop_oldest_active_session 和 sweep_idle_sessions 直接操作 session 状态，越过 manager 接口</td><td>中</td></tr><tr><td>配置状态（config.*）</td><td><code>config.py</code></td><td><code>config.py</code>（或专用的 settings manager）</td><td><code>config.py</code> + <code>xiaomusic.xiaomusic</code>（直接持有）</td><td>xiaomusic 直接持有 config 实例，多处代码通过 xiaomusic.config 访问，缺少统一的配置读取封装</td><td>低</td></tr><tr><td>事件订阅（_subscribers）</td><td><code>events.py</code></td><td><code>events.py</code>（EventBus 单例）</td><td><code>events.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>异步任务（running_task）</td><td><code>xiaomusic.py</code></td><td><code>xiaomusic.py</code>（统一管理）</td><td><code>xiaomusic.py</code> + 分散在各模块（_recovery_task, _next_timer, _duration_probe_task 等）</td><td>各模块自行创建 asyncio.Task，但 xiaomusic.running_task 只追踪主任务，子任务的 owner 不清晰</td><td>中</td></tr><tr><td>播放进度（_start_time, _duration）</td><td><code>device_player.py</code></td><td><code>device_player.py</code></td><td><code>device_player.py</code>（正确）</td><td>无偏差，但计算依赖轮询（get_if_xiaoai_is_playing()），不是事件驱动</td><td>低</td></tr><tr><td>relay 流 URL（stream_url）</td><td><code>relay/runtime.py</code></td><td><code>relay/runtime.py</code></td><td><code>relay/runtime.py</code>（正确）</td><td>无偏差</td><td>无</td></tr><tr><td>LinkPlaybackStrategy</td><td><code>link_strategy.py</code></td><td><code>link_strategy.py</code></td><td><code>relay/runtime.py</code>（持有）+ <code>xiaomusic.xiaomusic</code>（可选持有）</td><td>LinkPlaybackStrategy 可以从 xiaomusic 获取也可以独立创建，生命周期不明确</td><td>低</td></tr></tbody></table><h3 id="_1-2-高度可疑状态-已解决" tabindex="-1">1.2 高度可疑状态（已解决） <a class="header-anchor" href="#_1-2-高度可疑状态-已解决" aria-label="Permalink to &quot;1.2 高度可疑状态（已解决）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>问题</th><th>状态</th></tr></thead><tbody><tr><td>播放列表双写</td><td><code>device_player._play_list_items</code> 和 <code>music_library.music_list</code> 内容可能不一致</td><td>✅ 已解决：删除 <code>_play_list</code>，统一通过 <code>_get_playlist_names()</code> 派生</td></tr><tr><td>异步任务 owner 缺失</td><td><code>_recovery_task</code>、<code>_next_timer</code>、<code>_duration_probe_task</code> 创建者不明确</td><td>✅ 已标注：所有 task 创建处有 <code># owner: xxx</code> 注释</td></tr><tr><td>session 状态越界修改</td><td><code>relay_runtime</code> 绕过 <code>session_manager</code> 直接修改 session 状态</td><td>✅ 已解决：通过 <code>session_manager.stop_session()</code> API</td></tr><tr><td>source 注册逻辑分散</td><td>注册逻辑在 default_registry + source_registry + manager 三处</td><td>✅ 已解决：SiteMediaSourcePlugin 通过 LinkPreparer Protocol 解耦</td></tr></tbody></table><h2 id="_2-质量门禁判断" tabindex="-1">2. 质量门禁判断 <a class="header-anchor" href="#_2-质量门禁判断" aria-label="Permalink to &quot;2. 质量门禁判断&quot;">​</a></h2><h3 id="_2-1-严重偏差汇总" tabindex="-1">2.1 严重偏差汇总 <a class="header-anchor" href="#_2-1-严重偏差汇总" aria-label="Permalink to &quot;2.1 严重偏差汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>偏差类型</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>高严重程度</td><td>0</td><td>无架构级别矛盾</td></tr><tr><td>中严重程度</td><td>0</td><td>全部 4 个已解决（播放列表双写、session越界、task owner、source注册分散）</td></tr><tr><td>低严重程度</td><td>6</td><td>访问路径不干净、设备 model 直接修改、配置访问分散、轮询驱动、非单例访问等</td></tr></tbody></table><p><strong>结论</strong>：全部中严重偏差已解决。系统进入&quot;低风险技术债&quot;状态，剩余问题均为可管理的细节。</p><h3 id="_2-2-核心架构矛盾-无" tabindex="-1">2.2 核心架构矛盾（无） <a class="header-anchor" href="#_2-2-核心架构矛盾-无" aria-label="Permalink to &quot;2.2 核心架构矛盾（无）&quot;">​</a></h3><p>经过 S2 全面审计，未发现架构级别的根本性矛盾：</p><ul><li>Source 插件化设计合理，<code>SiteMediaSourcePlugin</code> 的 runtime_provider 依赖是已知问题，但不影响整体可运行性</li><li>API 边界清晰，WebUI 不直接访问 runtime</li><li>状态权威大部分正确，只有&quot;数据双写&quot;问题需要关注</li></ul><h2 id="_3-下一步建议" tabindex="-1">3. 下一步建议 <a class="header-anchor" href="#_3-下一步建议" aria-label="Permalink to &quot;3. 下一步建议&quot;">​</a></h2><h3 id="_3-1-已落地的低风险约束" tabindex="-1">3.1 已落地的低风险约束 <a class="header-anchor" href="#_3-1-已落地的低风险约束" aria-label="Permalink to &quot;3.1 已落地的低风险约束&quot;">​</a></h3><ol><li><strong>歌单事实与运行时队列分离</strong>：<code>music_library</code> 提供 membership，<code>device_player</code> 只为当前 session 保存稳定队列快照与索引。</li><li><strong>控制意图单入口</strong>：WebUI next/previous 不点名曲目，统一经 Public API、Coordinator、Transport 进入设备导航。</li><li><strong>随机 session 稳定</strong>：新 session 只洗牌一次；手动和自动 next/previous 均消费同一快照。</li><li><strong>异步任务 owner 明确</strong>：延迟任务受 session ID 约束，旧回调不得覆盖新播放状态。</li><li><strong>session 状态通过 manager 接口修改</strong>：relay session 不得被其他模块越界写入。</li></ol><h3 id="_3-2-中期重构-需要-adr" tabindex="-1">3.2 中期重构（需要 ADR） <a class="header-anchor" href="#_3-2-中期重构-需要-adr" aria-label="Permalink to &quot;3.2 中期重构（需要 ADR）&quot;">​</a></h3><ol><li><strong>Source 插件解耦</strong>：<code>SiteMediaSourcePlugin</code> 通过 <code>runtime_provider</code> 调用 runtime 的问题，需要通过 ADR 确定&quot;播放准备&quot;职责归属</li><li><strong>RelayRuntime 拆分</strong>：将策略选择（relay/direct/proxy）和播放编排（play+cast）分离</li><li><strong>AuthManager 拆分</strong>：认证状态管理和 runtime 管理应分离为不同模块</li></ol><h3 id="_3-3-长期架构演进" tabindex="-1">3.3 长期架构演进 <a class="header-anchor" href="#_3-3-长期架构演进" aria-label="Permalink to &quot;3.3 长期架构演进&quot;">​</a></h3><ol><li><strong>xiaomusic.xiaomusic 减肥</strong>：作为应用入口，不承担具体业务逻辑</li><li><strong>引入状态权威注册表</strong>：将每个状态的权威显式注册，所有状态变化必须经过权威对应的接口</li></ol><p>当前播放控制模型见 <a href="./playback-control-model.html"><code>playback-control-model.md</code></a>。</p><h2 id="_4-t07-校正-2026-07-28" tabindex="-1">4. T07 校正（2026-07-28） <a class="header-anchor" href="#_4-t07-校正-2026-07-28" aria-label="Permalink to &quot;4. T07 校正（2026-07-28）&quot;">​</a></h2><p>T03-T06 已落地后，播放 runtime 的实际权威为 <code>PlaybackRuntimeState.phase</code>、<code>LifecycleToken</code> 与 <code>PlaybackTaskRegistry</code>：Facade snapshot 只读投影 phase；Device arbiter 串行化命令；completion/failure policy 决定 timer completion 与 retry 行为。<code>_last_cmd</code> 仅保留为 legacy diagnostic，不能决定 Facade/state authority、failure/retry 或 completion 合法性。<code>_play_session_id</code> 只作 async media session invalidation id。</p><p>查询约束：<code>get_offset_duration</code>、Facade snapshot 与 <code>player_state</code> 不创建/取消 task，不调用 Mina，不写 runtime state，不隐式修复；异常只返回安全投影并记录日志。<code>POST /api/v1/play</code> 可返回 deferred <code>accepted=true, started=null</code>；stop accepted 不等于物理 STOPPED，需通过状态快照确认。</p>',26)]))}const y=e(r,[["render",c]]);export{p as __pageData,y as default};
